// src/app/components/SearchModal.tsx
import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router';
import { Search, X, Users, User, Calendar } from 'lucide-react';
import { teams, players, upcomingMatches } from '../../data/leagueData';
import { useLanguage } from '../context/LanguageContext';

interface SearchModalProps {
  isOpen: boolean;
  onClose: () => void;
}

export function SearchModal({ isOpen, onClose }: SearchModalProps) {
  const [searchTerm, setSearchTerm] = useState('');
  const navigate = useNavigate();
  const { t } = useLanguage();

  useEffect(() => {
    const handleEscape = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose();
    };
    document.addEventListener('keydown', handleEscape);
    return () => document.removeEventListener('keydown', handleEscape);
  }, [onClose]);

  if (!isOpen) return null;

  const filteredTeams = Object.values(teams).filter(team =>
    team.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const filteredPlayers = players.filter(player =>
    player.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const filteredMatches = upcomingMatches.filter(match =>
    match.homeTeam.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    match.awayTeam.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleSelect = (path: string) => {
    navigate(path);
    onClose();
    setSearchTerm('');
  };

  return (
    <div className="fixed inset-0 z-50 bg-black/95 backdrop-blur-lg">
      <div className="max-w-2xl mx-auto p-4">
        {/* Search Header */}
        <div className="flex items-center gap-3 mb-6">
          <div className="flex-1 relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
            <input
              type="text"
              placeholder={t('Search teams, players, matches...')}
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full pl-10 pr-4 py-3 rounded-lg text-white text-lg"
              style={{
                background: 'rgba(26, 31, 46, 0.9)',
                border: '1px solid rgba(255, 215, 0, 0.3)'
              }}
              autoFocus
            />
          </div>
          <button
            onClick={onClose}
            className="p-3 rounded-lg hover:bg-white/10 transition-colors"
          >
            <X className="w-6 h-6 text-white" />
          </button>
        </div>

        {/* Search Results */}
        <div className="space-y-6 max-h-[calc(100vh-120px)] overflow-y-auto">
          {/* Teams Results */}
          {filteredTeams.length > 0 && (
            <div>
              <h3 className="text-[#ffd700] font-semibold mb-2 flex items-center gap-2">
                <Users className="w-4 h-4" />
                {t('Teams')} ({filteredTeams.length})
              </h3>
              <div className="space-y-2">
                {filteredTeams.map(team => (
                  <button
                    key={team.id}
                    onClick={() => handleSelect(`/team/${team.id}`)}
                    className="w-full flex items-center gap-3 p-3 rounded-lg hover:bg-white/5 transition-colors text-left"
                  >
                    <div 
                      className="w-10 h-10 rounded-full flex items-center justify-center"
                      style={{ background: team.color }}
                    >
                      <span className="text-black font-bold">{team.shortName.charAt(0)}</span>
                    </div>
                    <div>
                      <p className="text-white font-semibold">{team.name}</p>
                      <p className="text-xs text-gray-400">{team.stadium}</p>
                    </div>
                  </button>
                ))}
              </div>
            </div>
          )}

          {/* Players Results */}
          {filteredPlayers.length > 0 && (
            <div>
              <h3 className="text-[#ffd700] font-semibold mb-2 flex items-center gap-2">
                <User className="w-4 h-4" />
                {t('Players')} ({filteredPlayers.length})
              </h3>
              <div className="space-y-2">
                {filteredPlayers.map(player => (
                  <button
                    key={player.id}
                    onClick={() => handleSelect(`/player/${player.id}`)}
                    className="w-full flex items-center gap-3 p-3 rounded-lg hover:bg-white/5 transition-colors text-left"
                  >
                    <div className="w-10 h-10 rounded-full bg-gray-700 flex items-center justify-center">
                      <span className="text-white font-bold">{player.number}</span>
                    </div>
                    <div className="flex-1">
                      <p className="text-white font-semibold">{player.name}</p>
                      <p className="text-xs text-gray-400">
                        {player.position} • {teams[player.teamId]?.name}
                      </p>
                    </div>
                    <div className="text-right">
                      <p className="text-[#ffd700] font-bold">{player.goals} {t('goals')}</p>
                      <p className="text-xs text-gray-400">{player.assists} {t('assists')}</p>
                    </div>
                  </button>
                ))}
              </div>
            </div>
          )}

          {/* Matches Results */}
          {filteredMatches.length > 0 && (
            <div>
              <h3 className="text-[#ffd700] font-semibold mb-2 flex items-center gap-2">
                <Calendar className="w-4 h-4" />
                {t('Matches')} ({filteredMatches.length})
              </h3>
              <div className="space-y-2">
                {filteredMatches.map(match => (
                  <button
                    key={match.id}
                    onClick={() => handleSelect(`/match/${match.id}`)}
                    className="w-full flex items-center justify-between p-3 rounded-lg hover:bg-white/5 transition-colors"
                  >
                    <div className="flex-1 text-right">
                      <p className="text-white font-semibold">{match.homeTeam.shortName}</p>
                    </div>
                    <div className="px-3">
                      <p className="text-[#ffd700] font-bold text-sm">{t('VS')}</p>
                      <p className="text-xs text-gray-500">{match.time}</p>
                    </div>
                    <div className="flex-1 text-left">
                      <p className="text-white font-semibold">{match.awayTeam.shortName}</p>
                    </div>
                  </button>
                ))}
              </div>
            </div>
          )}

          {/* No Results */}
          {searchTerm && filteredTeams.length === 0 && filteredPlayers.length === 0 && filteredMatches.length === 0 && (
            <div className="text-center py-12">
              <Search className="w-12 h-12 text-gray-600 mx-auto mb-3" />
              <p className="text-gray-400">{t('No results found for "{{term}}"', { term: searchTerm })}</p>
              <p className="text-sm text-gray-500 mt-1">{t('Try searching for teams, players, or matches')}</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
