// src/app/pages/MatchDetailsPage.tsx
import { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router';
import { ArrowLeft, Calendar, MapPin, Users, Clock, Share2 } from 'lucide-react';
import { supabase } from '../../lib/supabase';

interface Team {
  id: number;
  name: string;
  short_name: string;
  color: string;
  stadium?: string;
  logo_url?: string;
}

interface MatchEvent {
  id: number;
  match_id: number;
  type: string;
  minute: number;
  minute_extra?: number;
  player_id: number;
  player_name: string;
  team_id: number;
  assisted_by?: string;
  is_penalty?: boolean;
  is_own_goal?: boolean;
}

interface MatchDetails {
  id: number;
  home_team_id: number;
  away_team_id: number;
  home_score: number | null;
  away_score: number | null;
  status: string;
  matchweek: number;
  date: string;
  time: string;
  stadium: string;
  attendance: number | null;
  referee: string | null;
  match_minute?: number;
  match_second?: number;
  match_half?: string;
  injury_time?: number;
  homeTeam?: Team;
  awayTeam?: Team;
}

export function MatchDetailsPage() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [match, setMatch] = useState<MatchDetails | null>(null);
  const [events, setEvents] = useState<MatchEvent[]>([]);
  const [loading, setLoading] = useState(true);
  const [homeLogoError, setHomeLogoError] = useState(false);
  const [awayLogoError, setAwayLogoError] = useState(false);
  const [realtimeConnected, setRealtimeConnected] = useState(false);

  // Fetch initial data
  useEffect(() => {
    if (id) {
      fetchMatchDetails();
      fetchMatchEvents();
    }
  }, [id]);

  // Real-time subscription for match updates
  useEffect(() => {
    if (!id) return;

    // Subscribe to match updates
    const matchSubscription = supabase
      .channel(`match_${id}_updates`)
      .on(
        'postgres_changes',
        {
          event: 'UPDATE',
          schema: 'public',
          table: 'matches',
          filter: `id=eq.${id}`,
        },
        (payload) => {
          console.log('Match update received:', payload);
          const updatedMatch = payload.new;
          setMatch(prev => prev ? { ...prev, ...updatedMatch } : null);
          setRealtimeConnected(true);
        }
      )
      .subscribe();

    // Subscribe to new events
    const eventsSubscription = supabase
      .channel(`match_${id}_events`)
      .on(
        'postgres_changes',
        {
          event: 'INSERT',
          schema: 'public',
          table: 'match_events',
          filter: `match_id=eq.${id}`,
        },
        (payload) => {
          console.log('New event received:', payload);
          const newEvent = payload.new;
          setEvents(prev => [...prev, newEvent].sort((a, b) => a.minute - b.minute));
          setRealtimeConnected(true);
        }
      )
      .on(
        'postgres_changes',
        {
          event: 'DELETE',
          schema: 'public',
          table: 'match_events',
          filter: `match_id=eq.${id}`,
        },
        () => {
          console.log('Event deleted, refreshing events');
          fetchMatchEvents();
          setRealtimeConnected(true);
        }
      )
      .subscribe();

    return () => {
      matchSubscription.unsubscribe();
      eventsSubscription.unsubscribe();
    };
  }, [id]);

  // Poll for updates every 3 seconds as fallback (ensures data is always in sync)
  useEffect(() => {
    if (!id) return;

    const interval = setInterval(async () => {
      // Fetch latest match data
      const { data: matchData, error: matchError } = await supabase
        .from('matches')
        .select('*')
        .eq('id', id)
        .single();

      if (!matchError && matchData) {
        setMatch(prev => prev ? { ...prev, ...matchData } : null);
      }

      // Fetch latest events
      const { data: eventsData, error: eventsError } = await supabase
        .from('match_events')
        .select('*')
        .eq('match_id', id)
        .order('minute', { ascending: true });

      if (!eventsError && eventsData) {
        setEvents(eventsData);
      }
    }, 3000);

    return () => clearInterval(interval);
  }, [id]);

  const fetchMatchDetails = async () => {
    try {
      const { data, error } = await supabase
        .from('matches')
        .select(`
          *,
          homeTeam:home_team_id(id, name, short_name, color, stadium, logo_url),
          awayTeam:away_team_id(id, name, short_name, color, stadium, logo_url)
        `)
        .eq('id', id)
        .single();

      if (error) throw error;
      setMatch(data);
    } catch (error) {
      console.error('Error fetching match details:', error);
    }
  };

  const fetchMatchEvents = async () => {
    try {
      const { data, error } = await supabase
        .from('match_events')
        .select('*')
        .eq('match_id', id)
        .order('minute', { ascending: true });

      if (error) throw error;
      setEvents(data || []);
    } catch (error) {
      console.error('Error fetching events:', error);
    } finally {
      setLoading(false);
    }
  };

  const getEventIcon = (type: string) => {
    switch (type) {
      case 'goal': return '⚽';
      case 'yellow_card': return '🟨';
      case 'red_card': return '🟥';
      case 'substitution': return '🔄';
      case 'offside': return '🚩';
      case 'foul': return '⚠️';
      case 'penalty': return '🔴';
      case 'corner': return '⤴️';
      default: return '📋';
    }
  };

  const getEventText = (event: MatchEvent) => {
    switch (event.type) {
      case 'goal':
        let text = event.player_name;
        if (event.is_penalty) text += ' (Penalty)';
        if (event.is_own_goal) text += ' (OG)';
        if (event.assisted_by) {
          const assistPlayer = events.find(e => e.player_id === event.assisted_by);
          if (assistPlayer) text += ` (${assistPlayer.player_name})`;
        }
        return text;
      case 'yellow_card':
        return `${event.player_name}`;
      case 'red_card':
        return `${event.player_name}`;
      case 'substitution':
        return `${event.player_name}`;
      default:
        return event.player_name;
    }
  };

  const formatTime = () => {
    if (!match) return 'TBD';

    if (match.status === 'finished') {
      return 'FT';
    }
    if (match.status === 'scheduled') {
      return match.time || 'TBD';
    }

    // Live match - show actual time from database
    const minute = match.match_minute || 0;
    const second = match.match_second || 0;
    const injuryTime = match.injury_time || 0;

    if (minute >= 90) {
      return 'FT';
    }
    if (minute === 45 && injuryTime > 0) {
      return `HT +${injuryTime}`;
    }
    if (minute === 45) {
      return 'HT';
    }

    let displayMinute = minute;
    let extra = '';

    if (minute >= 45 && injuryTime > 0) {
      extra = ` +${injuryTime}`;
    }

    return `${displayMinute}:${second.toString().padStart(2, '0')}${extra}`;
  };

  const getLivePercentage = () => {
    if (!match) return 0;
    const minute = match.match_minute || 0;
    if (minute >= 90) return 100;
    return (minute / 90) * 100;
  };

  const handleShare = async () => {
    if (!match) return;
    const shareData = {
      title: `${match.homeTeam?.name} vs ${match.awayTeam?.name}`,
      text: `Follow the latest Ethiopian Premier League match details.`,
      url: window.location.href,
    };
    if (navigator.share) {
      await navigator.share(shareData);
    } else if (navigator.clipboard?.writeText) {
      await navigator.clipboard.writeText(shareData.url);
      alert('Link copied to clipboard!');
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="w-12 h-12 border-4 border-[#ffd700] border-t-transparent rounded-full animate-spin" />
      </div>
    );
  }

  if (!match) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="text-center">
          <p className="text-gray-400 mb-4">Match not found</p>
          <button onClick={() => navigate('/matches')} className="px-4 py-2 bg-[#ffd700] text-black rounded-lg font-semibold">
            Back to Matches
          </button>
        </div>
      </div>
    );
  }

  const homeEvents = events.filter(e => e.team_id === match.home_team_id);
  const awayEvents = events.filter(e => e.team_id === match.away_team_id);
  const isLive = match.status === 'live';
  const isFinished = match.status === 'finished';

  return (
    <div className="min-h-screen bg-gradient-to-b from-[#0a0e1a] to-[#0a0e1a]">
      {/* Realtime Connection Status */}
      {realtimeConnected && (
        <div className="fixed bottom-4 right-4 z-50">
          <div className="flex items-center gap-2 px-3 py-1.5 rounded-full bg-green-500/20 border border-green-500/30">
            <div className="w-2 h-2 bg-green-500 rounded-full animate-pulse" />
            <span className="text-green-500 text-xs">Live Updates Active</span>
          </div>
        </div>
      )}

      {/* Header */}
      <div className="sticky top-0 z-10 backdrop-blur-xl bg-black/80 border-b border-white/10">
        <div className="px-4 py-3 flex items-center justify-between">
          <button onClick={() => navigate('/matches')} className="flex items-center gap-2 text-gray-400 hover:text-white transition-colors">
            <ArrowLeft className="w-5 h-5" />
            <span>Back</span>
          </button>
          <div className="flex gap-2">
            <button onClick={handleShare} className="p-2 hover:bg-white/10 rounded-lg transition-colors">
              <Share2 className="w-5 h-5 text-gray-400" />
            </button>
          </div>
        </div>
      </div>

      {/* Score Header */}
      <div className="px-4 pt-6 pb-4 bg-gradient-to-b from-[#1a1f2e]/50 to-transparent">
        <div className="flex items-center justify-between gap-2 mb-6">
          {/* Home Team */}
          <div className="flex-1 text-center">
            <div className="w-24 h-24 mx-auto mb-3 rounded-full overflow-hidden flex items-center justify-center shadow-xl" style={{
              background: `${match.homeTeam?.color}20`,
              border: `3px solid ${match.homeTeam?.color}`
            }}>
              {match.homeTeam?.logo_url && !homeLogoError ? (
                <img
                  src={match.homeTeam.logo_url}
                  alt={match.homeTeam.name}
                  className="w-full h-full object-cover"
                  onError={() => setHomeLogoError(true)}
                />
              ) : (
                <div className="w-full h-full flex items-center justify-center text-3xl font-black" style={{ background: match.homeTeam?.color, color: '#000' }}>
                  {match.homeTeam?.short_name?.charAt(0) || match.homeTeam?.name?.charAt(0)}
                </div>
              )}
            </div>
            <h2 className="text-white font-bold text-lg mb-1">{match.homeTeam?.name}</h2>
            <p className="text-xs text-gray-400">{match.homeTeam?.short_name}</p>
          </div>

          {/* Score */}
          <div className="text-center">
            <div className="text-5xl font-black text-white mb-2">
              {match.home_score !== null ? match.home_score : '?'} - {match.away_score !== null ? match.away_score : '?'}
            </div>
            {isLive && (
              <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-red-500/20">
                <div className="w-2 h-2 bg-red-500 rounded-full animate-pulse" />
                <span className="text-red-500 text-xs font-semibold">LIVE</span>
                <span className="text-red-400 text-xs font-mono">{formatTime()}</span>
              </div>
            )}
            {isFinished && (
              <span className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-gray-500/20">
                <span className="text-gray-400 text-xs font-semibold">FULL TIME</span>
              </span>
            )}
            {!isLive && !isFinished && (
              <span className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-blue-500/20">
                <span className="text-blue-400 text-xs font-semibold">{match.time}</span>
              </span>
            )}
          </div>

          {/* Away Team */}
          <div className="flex-1 text-center">
            <div className="w-24 h-24 mx-auto mb-3 rounded-full overflow-hidden flex items-center justify-center shadow-xl" style={{
              background: `${match.awayTeam?.color}20`,
              border: `3px solid ${match.awayTeam?.color}`
            }}>
              {match.awayTeam?.logo_url && !awayLogoError ? (
                <img
                  src={match.awayTeam.logo_url}
                  alt={match.awayTeam.name}
                  className="w-full h-full object-cover"
                  onError={() => setAwayLogoError(true)}
                />
              ) : (
                <div className="w-full h-full flex items-center justify-center text-3xl font-black" style={{ background: match.awayTeam?.color, color: '#000' }}>
                  {match.awayTeam?.short_name?.charAt(0) || match.awayTeam?.name?.charAt(0)}
                </div>
              )}
            </div>
            <h2 className="text-white font-bold text-lg mb-1">{match.awayTeam?.name}</h2>
            <p className="text-xs text-gray-400">{match.awayTeam?.short_name}</p>
          </div>
        </div>

        {/* Live Progress Bar */}
        {isLive && (
          <div className="mt-4">
            <div className="flex justify-between text-xs text-gray-500 mb-1">
              <span>1st Half</span>
              <span className="font-mono">{formatTime()}</span>
              <span>2nd Half</span>
            </div>
            <div className="w-full bg-gray-700 rounded-full h-1.5 overflow-hidden">
              <div
                className="bg-gradient-to-r from-red-500 to-red-600 h-full rounded-full transition-all duration-500"
                style={{ width: `${getLivePercentage()}%` }}
              />
            </div>
          </div>
        )}

        {/* Match Info */}
        <div className="mt-6 flex flex-wrap items-center justify-center gap-4 text-xs text-gray-500">
          <div className="flex items-center gap-1">
            <Calendar className="w-3 h-3" />
            <span>{new Date(match.date).toLocaleDateString()}</span>
          </div>
          <div className="flex items-center gap-1">
            <Clock className="w-3 h-3" />
            <span>{match.time || 'TBD'}</span>
          </div>
          <div className="flex items-center gap-1">
            <MapPin className="w-3 h-3" />
            <span>{match.stadium}</span>
          </div>
          <div className="flex items-center gap-1">
            <Users className="w-3 h-3" />
            <span>Ref: {match.referee || 'TBD'}</span>
          </div>
        </div>
      </div>

      {/* Match Events */}
      <div className="px-4 py-6">
        <div className="hidden md:grid md:grid-cols-2 gap-6">
          {/* Home Team Events */}
          <div>
            <div className="flex items-center gap-2 mb-4 pb-2 border-b border-white/10">
              {match.homeTeam?.logo_url && !homeLogoError ? (
                <img src={match.homeTeam.logo_url} alt="" className="w-5 h-5 rounded-full" />
              ) : (
                <div className="w-3 h-3 rounded-full" style={{ background: match.homeTeam?.color }} />
              )}
              <h3 className="text-white font-bold">{match.homeTeam?.name}</h3>
            </div>
            <div className="space-y-3">
              {homeEvents.length === 0 ? (
                <div className="text-center py-8 text-gray-500 text-sm">No events yet</div>
              ) : (
                homeEvents.map((event) => (
                  <div key={event.id} className="flex items-center justify-end gap-2">
                    <div className="text-right">
                      <p className="text-white font-semibold text-sm">{getEventText(event)}</p>
                      {event.type === 'goal' && event.assisted_by && (
                        <p className="text-xs text-gray-500">Assist</p>
                      )}
                    </div>
                    <div className="flex items-center gap-1">
                      <span className="text-[#ffd700] font-bold text-sm">{event.minute}'</span>
                      <span className="text-2xl">{getEventIcon(event.type)}</span>
                    </div>
                  </div>
                ))
              )}
            </div>
          </div>

          {/* Away Team Events */}
          <div>
            <div className="flex items-center gap-2 mb-4 pb-2 border-b border-white/10">
              {match.awayTeam?.logo_url && !awayLogoError ? (
                <img src={match.awayTeam.logo_url} alt="" className="w-5 h-5 rounded-full" />
              ) : (
                <div className="w-3 h-3 rounded-full" style={{ background: match.awayTeam?.color }} />
              )}
              <h3 className="text-white font-bold">{match.awayTeam?.name}</h3>
            </div>
            <div className="space-y-3">
              {awayEvents.length === 0 ? (
                <div className="text-center py-8 text-gray-500 text-sm">No events yet</div>
              ) : (
                awayEvents.map((event) => (
                  <div key={event.id} className="flex items-center gap-2">
                    <div className="flex items-center gap-1">
                      <span className="text-2xl">{getEventIcon(event.type)}</span>
                      <span className="text-[#ffd700] font-bold text-sm">{event.minute}'</span>
                    </div>
                    <div className="text-left">
                      <p className="text-white font-semibold text-sm">{getEventText(event)}</p>
                      {event.type === 'goal' && event.assisted_by && (
                        <p className="text-xs text-gray-500">Assist</p>
                      )}
                    </div>
                  </div>
                ))
              )}
            </div>
          </div>
        </div>

        {/* Mobile Layout */}
        <div className="md:hidden">
          <div className="relative">
            <div className="absolute left-1/2 transform -translate-x-1/2 w-0.5 h-full bg-gradient-to-b from-[#ffd700]/50 via-[#ffd700] to-[#ffd700]/50" />
            {events.length === 0 ? (
              <div className="text-center py-12 text-gray-500">No events recorded</div>
            ) : (
              events.map((event) => {
                const isHome = event.team_id === match.home_team_id;
                return (
                  <div key={event.id} className={`flex items-center gap-3 mb-4 ${isHome ? 'flex-row' : 'flex-row-reverse'}`}>
                    <div className={`flex-1 ${isHome ? 'text-right' : 'text-left'}`}>
                      <p className="text-white font-semibold text-sm">{getEventText(event)}</p>
                      {event.type === 'goal' && event.assisted_by && (
                        <p className="text-xs text-gray-500">Assist</p>
                      )}
                    </div>
                    <div className="relative z-10 flex flex-col items-center">
                      <div className="w-8 h-8 rounded-full flex items-center justify-center bg-[#1a1f2e] border-2" style={{ borderColor: isHome ? match.homeTeam?.color : match.awayTeam?.color }}>
                        <span className="text-sm">{getEventIcon(event.type)}</span>
                      </div>
                      <span className="text-[#ffd700] text-xs font-bold mt-1">{event.minute}'</span>
                    </div>
                    <div className="flex-1" />
                  </div>
                );
              })
            )}
          </div>
        </div>

        {/* Match Stats */}
        <div className="mt-8 p-4 rounded-xl" style={{ background: 'rgba(26, 31, 46, 0.5)' }}>
          <div className="flex justify-between items-center mb-4">
            <div className="flex items-center gap-2">
              {match.homeTeam?.logo_url && !homeLogoError ? (
                <img src={match.homeTeam.logo_url} alt="" className="w-4 h-4 rounded-full" />
              ) : (
                <div className="w-3 h-3 rounded-full" style={{ background: match.homeTeam?.color }} />
              )}
              <span className="text-gray-400 text-sm">{match.homeTeam?.short_name}</span>
            </div>
            <span className="text-[#ffd700] text-xs font-semibold">MATCH STATS</span>
            <div className="flex items-center gap-2">
              <span className="text-gray-400 text-sm">{match.awayTeam?.short_name}</span>
              {match.awayTeam?.logo_url && !awayLogoError ? (
                <img src={match.awayTeam.logo_url} alt="" className="w-4 h-4 rounded-full" />
              ) : (
                <div className="w-3 h-3 rounded-full" style={{ background: match.awayTeam?.color }} />
              )}
            </div>
          </div>

          {/* Possession */}
          <div className="mb-3">
            <div className="flex justify-between text-xs text-gray-500 mb-1">
              <span>Possession</span>
              <span>50% | 50%</span>
            </div>
            <div className="flex h-1.5 rounded-full overflow-hidden">
              <div className="h-full" style={{ width: '50%', background: match.homeTeam?.color }} />
              <div className="h-full" style={{ width: '50%', background: match.awayTeam?.color }} />
            </div>
          </div>

          {/* Shots */}
          <div className="flex justify-between text-xs text-gray-500">
            <div className="flex gap-2">
              <span>Shots: {events.filter(e => e.type === 'goal' && e.team_id === match.home_team_id).length}</span>
              <span>On Target: {events.filter(e => e.type === 'goal' && e.team_id === match.home_team_id).length}</span>
            </div>
            <div className="flex gap-2">
              <span>On Target: {events.filter(e => e.type === 'goal' && e.team_id === match.away_team_id).length}</span>
              <span>Shots: {events.filter(e => e.type === 'goal' && e.team_id === match.away_team_id).length}</span>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}