import { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router';
import { AlertCircle, ArrowLeft } from 'lucide-react';
import { supabase } from '../../lib/supabase';
import { useLanguage } from '../context/LanguageContext';

export function ResetPasswordPage() {
  const navigate = useNavigate();
  const { t } = useLanguage();
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [loading, setLoading] = useState(false);
  const [isValid, setIsValid] = useState(false);
  const [checking, setChecking] = useState(true);

  useEffect(() => {
    const hash = window.location.hash;

    if (hash && hash.includes('access_token')) {
      setIsValid(true);
      setChecking(false);
      return;
    }

    supabase.auth.getSession().then(({ data: { session } }) => {
      if (session) {
        setIsValid(true);
      } else {
        setError(t('Invalid or expired reset link'));
      }
      setChecking(false);
    });
  }, [t]);

  const handleSubmit = async (event: React.FormEvent) => {
    event.preventDefault();
    setError('');
    setSuccess('');

    if (password.length < 6) {
      setError(t('Password must be at least 6 characters'));
      return;
    }

    if (password !== confirmPassword) {
      setError(t('Passwords do not match'));
      return;
    }

    setLoading(true);

    try {
      const { error: updateError } = await supabase.auth.updateUser({ password });
      if (updateError) throw updateError;

      setSuccess(t('Password updated! Redirecting...'));
      setTimeout(() => navigate('/login', { replace: true }), 2000);
    } catch (err: any) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  if (checking) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="w-12 h-12 border-4 border-[#ffd700] border-t-transparent rounded-full animate-spin" />
      </div>
    );
  }

  if (!isValid && error) {
    return (
      <div className="min-h-screen flex items-center justify-center px-4">
        <div className="text-center">
          <AlertCircle className="w-16 h-16 text-red-500 mx-auto mb-4" />
          <h2 className="text-2xl text-white mb-2">{t('Invalid Link')}</h2>
          <p className="text-gray-400 mb-6">{error}</p>
          <Link to="/forgot-password" className="px-6 py-2 bg-[#ffd700] text-black rounded-lg">
            {t('Request New Link')}
          </Link>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex items-center justify-center px-4">
      <div className="w-full max-w-md">
        <div className="text-center mb-8">
          <h1 className="text-3xl text-white">{t('Reset Password')}</h1>
          <p className="text-gray-400 mt-2">{t('Enter your new password')}</p>
        </div>

        <div className="rounded-xl p-6" style={{ background: 'rgba(26, 31, 46, 0.8)' }}>
          {error && <div className="mb-4 p-3 rounded-lg bg-red-500/10 text-red-500 text-sm">{error}</div>}
          {success && <div className="mb-4 p-3 rounded-lg bg-green-500/10 text-green-500 text-sm">{success}</div>}

          <form onSubmit={handleSubmit} className="space-y-4">
            <div>
              <label className="block text-sm text-gray-400 mb-2">{t('New Password')}</label>
              <input
                type="password"
                value={password}
                onChange={(event) => setPassword(event.target.value)}
                className="w-full px-4 py-3 rounded-lg text-white bg-black/50 border border-white/10"
                placeholder="******** (min 6 characters)"
                required
                minLength={6}
              />
            </div>

            <div>
              <label className="block text-sm text-gray-400 mb-2">{t('Confirm Password')}</label>
              <input
                type="password"
                value={confirmPassword}
                onChange={(event) => setConfirmPassword(event.target.value)}
                className="w-full px-4 py-3 rounded-lg text-white bg-black/50 border border-white/10"
                placeholder="********"
                required
              />
            </div>

            <button type="submit" disabled={loading} className="w-full py-3 rounded-lg text-black font-semibold bg-[#ffd700] disabled:opacity-50">
              {loading ? t('Updating...') : t('Reset Password')}
            </button>
          </form>

          <div className="mt-6 text-center">
            <Link to="/login" className="text-sm text-gray-400 hover:text-white flex items-center justify-center gap-1">
              <ArrowLeft className="w-3 h-3" />
              {t('Back to Login')}
            </Link>
          </div>
        </div>
      </div>
    </div>
  );
}
