// src/app/pages/MatchesPage.tsx
import { useState, useEffect, useCallback } from 'react';
import { useNavigate } from 'react-router';
import { Calendar } from 'lucide-react';
import { MatchCard } from '../components/MatchCard';
import { supabase } from '../../lib/supabase';
import { useLanguage } from '../context/LanguageContext';

interface Team {
  id: number;
  name: string;
  short_name: string;
  color: string;
  logo_url?: string;
}

interface Match {
  id: number;
  home_team_id: number;
  away_team_id: number;
  home_score: number | null;
  away_score: number | null;
  status: string;
  matchweek: number;
  date: string;
  time: string;
  stadium: string;
  match_minute?: number;
  match_second?: number;
  match_half?: string;
  injury_time_first_half?: number;
  injury_time_second_half?: number;
  homeTeam?: Team;
  awayTeam?: Team;
}

export function MatchesPage() {
  const { t } = useLanguage();
  const [matches, setMatches] = useState<Match[]>([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState('all');
  const [liveUpdates, setLiveUpdates] = useState<Record<number, { minute: number; second: number }>>({});

  useEffect(() => {
    fetchMatches();

    const subscription = supabase
      .channel('matches_changes')
      .on(
        'postgres_changes',
        {
          event: 'UPDATE',
          schema: 'public',
          table: 'matches',
          filter: 'status=eq.live',
        },
        (payload) => {
          const updatedMatch = payload.new;

          setMatches((previous) => previous.map((match) => (match.id === updatedMatch.id ? { ...match, ...updatedMatch } : match)));

          if (updatedMatch.match_minute !== undefined) {
            setLiveUpdates((previous) => ({
              ...previous,
              [updatedMatch.id]: {
                minute: updatedMatch.match_minute,
                second: updatedMatch.match_second || 0,
              },
            }));
          }
        },
      )
      .subscribe();

    return () => {
      subscription.unsubscribe();
    };
  }, []);

  useEffect(() => {
    const interval = setInterval(async () => {
      const liveMatches = matches.filter((match) => match.status === 'live');
      if (liveMatches.length === 0) return;

      for (const match of liveMatches) {
        const { data, error } = await supabase
          .from('matches')
          .select('match_minute, match_second, home_score, away_score')
          .eq('id', match.id)
          .single();

        if (!error && data) {
          setMatches((previous) => previous.map((item) => (item.id === match.id ? { ...item, ...data } : item)));
          setLiveUpdates((previous) => ({
            ...previous,
            [match.id]: {
              minute: data.match_minute || 0,
              second: data.match_second || 0,
            },
          }));
        }
      }
    }, 3000);

    return () => clearInterval(interval);
  }, [matches]);

  const [imageErrors, setImageErrors] = useState<Record<number, boolean>>({});

  const fetchMatches = useCallback(async () => {
    try {
      const { data, error } = await supabase
        .from('matches')
        .select(`
          *,
          homeTeam:home_team_id(id, name, short_name, color, logo_url),
          awayTeam:away_team_id(id, name, short_name, color, logo_url)
        `)
        .order('date', { ascending: false });

      if (error) throw error;
      setMatches(data || []);

      const updates: Record<number, { minute: number; second: number }> = {};
      (data || [])
        .filter((match) => match.status === 'live')
        .forEach((match: Match) => {
          updates[match.id] = {
            minute: match.match_minute || 0,
            second: match.match_second || 0,
          };
        });
      setLiveUpdates(updates);
    } catch (error) {
      console.error('Error fetching matches:', error);
    } finally {
      setLoading(false);
    }
  }, []);

  // Initial fetch
  useEffect(() => {
    fetchMatches();
  }, [fetchMatches]);

  // Set up real-time subscription for ALL changes
  useEffect(() => {
    // Subscribe to INSERT, UPDATE, DELETE events
    const subscription = supabase
      .channel('matches_live')
      .on(
        'postgres_changes',
        {
          event: 'INSERT',
          schema: 'public',
          table: 'matches',
        },
        (payload) => {
          console.log('New match inserted:', payload);
          // Add the new match to the list
          setMatches(prev => [payload.new as Match, ...prev]);
        }
      )
      .on(
        'postgres_changes',
        {
          event: 'UPDATE',
          schema: 'public',
          table: 'matches',
        },
        (payload) => {
          console.log('Match updated:', payload);
          // Update the match in the list
          setMatches(prev =>
            prev.map(match =>
              match.id === payload.new.id
                ? { ...match, ...payload.new }
                : match
            )
          );
        }
      )
      .on(
        'postgres_changes',
        {
          event: 'DELETE',
          schema: 'public',
          table: 'matches',
        },
        (payload) => {
          console.log('Match deleted:', payload);
          // Remove the deleted match
          setMatches(prev => prev.filter(match => match.id !== payload.old.id));
        }
      )
      .subscribe();

    return () => {
      subscription.unsubscribe();
    };
  }, []);

  // Local timer for smooth second updates on live matches
  useEffect(() => {
    const interval = setInterval(() => {
      setMatches(prev =>
        prev.map(match => {
          if (match.status !== 'live') return match;

          // Increment seconds locally for smooth UI
          let newSecond = (match.match_second || 0) + 1;
          let newMinute = match.match_minute || 0;

          if (newSecond >= 60) {
            newSecond = 0;
            newMinute = newMinute + 1;
          }

          return {
            ...match,
            match_second: newSecond,
            match_minute: newMinute,
          };
        })
      );
    }, 1000);

    return () => clearInterval(interval);
  }, []);

  const filteredMatches = matches.filter((match) => (filter === 'all' ? true : match.status === filter));

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="w-12 h-12 border-4 border-[#ffd700] border-t-transparent rounded-full animate-spin" />
      </div>
    );
  }

  return (
    <div className="pb-20">
      <div className="px-4 pt-6 pb-4">
        <h1 className="text-3xl text-white flex items-center gap-2" style={{ fontFamily: 'Inter, sans-serif', fontWeight: 900 }}>
          <Calendar className="w-8 h-8 text-[#ffd700]" />
          {t('Fixtures & Results')}
        </h1>
        <p className="text-gray-400">{t('Season 2025/26 • Ethiopian Premier League')}</p>
      </div>

      <div className="px-4 mb-6">
        <div className="flex gap-2 overflow-x-auto pb-2">
          {['all', 'scheduled', 'live', 'finished'].map((status) => (
            <button
              key={status}
              onClick={() => setFilter(status)}
              className={`px-4 py-2 rounded-xl font-semibold transition-all whitespace-nowrap ${filter === status ? 'text-black' : 'text-gray-400'}`}
              style={{ background: filter === status ? '#ffd700' : 'rgba(26, 31, 46, 0.8)' }}
            >
              {status === 'all'
                ? t('All Matches')
                : status === 'scheduled'
                  ? t('Upcoming')
                  : t(status.charAt(0).toUpperCase() + status.slice(1))}
            </button>
          ))}
        </div>
      </div>

      <div className="px-4 space-y-4">
        {filteredMatches.length === 0 ? (
          <div className="text-center py-12 rounded-xl" style={{ background: 'rgba(26, 31, 46, 0.8)' }}>
            <Calendar className="w-12 h-12 text-gray-600 mx-auto mb-3" />
            <p className="text-gray-400">{t('No matches found')}</p>
          </div>
        ) : (
          filteredMatches.map((match) => {
            const displayStatus = match.status === 'scheduled' ? 'upcoming' : (match.status as 'live' | 'upcoming' | 'finished');
            const liveUpdate = liveUpdates[match.id];

            return (
              <MatchCard
                key={match.id}
                id={String(match.id)}
                homeTeam={match.homeTeam || { id: 0, name: t('Unknown'), short_name: 'UNK', color: '#666' }}
                awayTeam={match.awayTeam || { id: 0, name: t('Unknown'), short_name: 'UNK', color: '#666' }}
                homeScore={match.home_score}
                awayScore={match.away_score}
                status={displayStatus}
                time={match.time}
                date={match.date}
                stadium={match.stadium}

                matchMinute={liveUpdate?.minute ?? match.match_minute}
                matchSecond={match.match_second}
                injuryTime={match.injury_time_first_half || match.injury_time_second_half}
              />
            );
          })
        )}
      </div>
    </div>
  );
}
